/**
 * Business Rules Engine - Pharmacy-specific field validation
 * 
 * This module validates each extracted field against pharmacy-specific business rules.
 * It NEVER trusts OCR output directly - always passes through validation.
 * 
 * Validation rules for each field type:
 * - Medicine names: length, allowed characters, no numbers at start, no garbage
 * - Batch numbers: format, length, no auto-generated, pattern consistency
 * - Prices: MRP > PTR > PTS relationship, reasonable ranges
 * - GST: valid rates (0/5/6/12/18/28), CGST = SGST for intra-state
 * - Dates: mfg before expiry, not expired, reasonable ranges
 * - HSN codes: must start with 30 for medicines, 4-8 digits
 * - Quantities: reasonable range, no suspicious round numbers
 * - Manufacturer: known manufacturer check, name consistency
 */

import { StandardField, FieldValidationResult, ValidatedItem } from './documentModel';
import { ParsedItem } from './ocrParser';

// ── Business Rules Configuration ─────────────────────────────────────

export interface BusinessRulesConfig {
  enableMedicineNameValidation: boolean;
  enableBatchValidation: boolean;
  enablePriceValidation: boolean;
  enableGSTValidation: boolean;
  enableDateValidation: boolean;
  enableHSNValidation: boolean;
  enableQuantityValidation: boolean;
  enableManufacturerValidation: boolean;
  enableCrossFieldValidation: boolean;
  autoCorrectThreshold: number;    // Confidence above which auto-correction is applied
  reviewThreshold: number;          // Confidence below which manual review is required
}

export const DEFAULT_BUSINESS_RULES_CONFIG: BusinessRulesConfig = {
  enableMedicineNameValidation: true,
  enableBatchValidation: true,
  enablePriceValidation: true,
  enableGSTValidation: true,
  enableDateValidation: true,
  enableHSNValidation: true,
  enableQuantityValidation: true,
  enableManufacturerValidation: true,
  enableCrossFieldValidation: true,
  autoCorrectThreshold: 85,
  reviewThreshold: 60,
};

// ── Validation Thresholds ────────────────────────────────────────────

const MEDICINE_NAME = {
  minLength: 3,
  maxLength: 200,
  minAlphaChars: 3,
  pattern: /^[a-zA-Z0-9\s().%\/\[\]\-]+$/,
  startsWithLetter: /^[a-zA-Z]/,
  noDates: /\b\d{4}-\d{2}-\d{2}\b/,
  noBatchPatterns: /^(?:batch|bt|lot|bno)[\s\-]/i,
};

const BATCH_NUMBER = {
  minLength: 3,
  maxLength: 20,
  pattern: /^[A-Z0-9\-]{3,15}$/i,
  autoGenerated: /^(?:batch|auto|test)[\-_]/i,
  onlyDigits: /^\d+$/,
  looksLikeDate: /^\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}$/,
};

const PRICE = {
  minMrp: 0.01,
  maxMrp: 100000,
  minPtr: 0.01,
  maxPtr: 100000,
  minPts: 0.01,
  maxPts: 100000,
  maxDiscountPercent: 50,
  decimalPlaces: 2,
};

const GST = {
  validRates: [0, 5, 6, 12, 18, 28] as const,
  maxRate: 28,
  cgstSgstTolerance: 0.01, // CGST and SGST should be nearly equal
};

const DATE = {
  minExpiryYear: 2020,
  maxExpiryYear: 2050,
  minMfgYear: 2020,
  maxMfgYear: 2030,
  maxMfgAge: 2,      // Max years since manufacturing
  minExpiryWarningDays: 30, // Warn if expiring within 30 days
};

const HSN = {
  minLength: 4,
  maxLength: 8,
  pattern: /^\d{4,8}$/,
  medicinePrefix: /^30/,
  surgicalPrefix: /^90/,
};

const QUANTITY = {
  min: 1,
  max: 100000,
  suspiciousRoundThreshold: 1000,
};

const MANUFACTURER = {
  minLength: 2,
  maxLength: 100,
};

// ── Known Manufacturer Database (subset) ─────────────────────────────

const KNOWN_MANUFACTURERS = new Set([
  'sun pharma', 'cipla', 'dr reddy', 'lupin', 'aurobinbo', 'divis lab',
  'torrent', 'alembic', 'zydus', 'intas', 'mankind', 'glenmark',
  'hetero', 'natco', 'granules', 'ajanta', 'fdc', 'micro labs',
  'emcure', 'wockhardt', 'ipca', 'united lab', 'sanofi', 'pfizer',
  'gsk', 'abbott', 'bayer', 'novartis', 'mylan', 'sandoz', 'fresenius',
  'baxter', 'serum institute', 'biocon', 'strides', 'alcon', 'merck',
  'ranbaxy', 'dabur', 'hamdard', 'baidyanath', 'macleods', 'leeford',
  'zota', 'healing pharma', 'indian drugs', 'shreya life', 'systopic',
]);

// ── Business Rule Result ─────────────────────────────────────────────

export interface BusinessRuleResult {
  field: string;
  fieldType: BusinessFieldType;
  originalValue: string;
  normalizedValue: string;
  isValid: boolean;
  confidence: number;
  severity: BusinessRuleSeverity;
  rulesApplied: string[];
  issues: string[];
  suggestions: string[];
  autoCorrected: boolean;
}

export enum BusinessFieldType {
  MEDICINE_NAME = 'medicine_name',
  BATCH_NUMBER = 'batch_number',
  EXPIRY_DATE = 'expiry_date',
  MFG_DATE = 'mfg_date',
  QUANTITY = 'quantity',
  FREE_QTY = 'free_qty',
  SCHEME_QTY = 'scheme_qty',
  UNIT_PRICE = 'unit_price',
  MRP = 'mrp',
  PTR = 'ptr',
  PTS = 'pts',
  TOTAL_AMOUNT = 'total_amount',
  DISCOUNT_PERCENT = 'discount_percent',
  TAXABLE_VALUE = 'taxable_value',
  GST_RATE = 'gst_rate',
  CGST_AMOUNT = 'cgst_amount',
  SGST_AMOUNT = 'sgst_amount',
  IGST_AMOUNT = 'igst_amount',
  HSN_CODE = 'hsn_code',
  MANUFACTURER = 'manufacturer',
  STRENGTH = 'strength',
  PACK_SIZE = 'pack_size',
  SCHEDULE_TYPE = 'schedule_type',
  BARCODE = 'barcode',
}

export enum BusinessRuleSeverity {
  CRITICAL = 'critical',   // Data cannot be used without correction
  WARNING = 'warning',      // Data likely correct but should be verified
  INFO = 'info',            // Minor issue, can be auto-corrected
}

// ── Item-Level Business Rules Result ─────────────────────────────────

export interface ItemBusinessRulesResult {
  itemId: string;
  results: BusinessRuleResult[];
  overallConfidence: number;
  overallSeverity: BusinessRuleSeverity;
  isUsable: boolean;
  criticalIssues: string[];
  warnings: string[];
  autoCorrections: AutoCorrection[];
}

export interface AutoCorrection {
  field: string;
  originalValue: string;
  correctedValue: string;
  rule: string;
  confidence: number;
}

// ── Batch-Level Results ──────────────────────────────────────────────

export interface BatchBusinessRulesResult {
  totalItems: number;
  usableItems: number;
  itemsNeedingReview: number;
  overallConfidence: number;
  autoSaveEligible: boolean;
  results: ItemBusinessRulesResult[];
  summary: {
    totalCriticalIssues: number;
    totalWarnings: number;
    totalAutoCorrections: number;
    fieldsWithLowConfidence: string[];
    suggestedManualReview: boolean;
  };
}

// ═══════════════════════════════════════════════════════════════════
// BUSINESS RULES ENGINE CLASS
// ═══════════════════════════════════════════════════════════════════

export class BusinessRulesEngine {
  private config: BusinessRulesConfig;

  constructor(config: Partial<BusinessRulesConfig> = {}) {
    this.config = { ...DEFAULT_BUSINESS_RULES_CONFIG, ...config };
  }

  /**
   * Validate a single parsed item against all applicable business rules
   */
  validateItem(item: ParsedItem): ItemBusinessRulesResult {
    const results: BusinessRuleResult[] = [];
    const autoCorrections: AutoCorrection[] = [];

    // Apply each enabled rule group
    if (this.config.enableMedicineNameValidation) {
      const result = this.validateMedicineName(item.name, item);
      results.push(result);
      if (result.autoCorrected) {
        autoCorrections.push({
          field: 'name',
          originalValue: result.originalValue,
          correctedValue: result.normalizedValue,
          rule: 'medicine_name_validation',
          confidence: result.confidence,
        });
      }
    }

    if (this.config.enableBatchValidation) {
      const result = this.validateBatchNumber(item.batchNumber);
      results.push(result);
      if (result.autoCorrected) {
        autoCorrections.push({
          field: 'batchNumber',
          originalValue: result.originalValue,
          correctedValue: result.normalizedValue,
          rule: 'batch_format_validation',
          confidence: result.confidence,
        });
      }
    }

    if (this.config.enableDateValidation) {
      results.push(this.validateExpiryDate(item.expiryDate, item.mfgDate));
      results.push(this.validateMfgDate(item.mfgDate, item.expiryDate));
    }

    if (this.config.enableQuantityValidation) {
      results.push(this.validateQuantity(item.quantity));
      results.push(this.validateFreeQty(item.freeQty, item.quantity));
    }

    if (this.config.enablePriceValidation) {
      results.push(this.validateUnitPrice(item.unitPrice, item.mrp, item.ptr));
      results.push(this.validateMRP(item.mrp, item.unitPrice));
      results.push(this.validateTotalAmount(item.totalAmount, item.quantity, item.unitPrice));
    }

    if (this.config.enableGSTValidation) {
      results.push(this.validateGSTRate(item.gstRate));
      results.push(this.validateGSTAmounts(item.gstRate, item.cgstAmount, item.sgstAmount, item.igstAmount, item.taxableValue));
    }

    if (this.config.enableHSNValidation) {
      results.push(this.validateHSNCode(item.hsnCode));
    }

    if (this.config.enableManufacturerValidation) {
      results.push(this.validateManufacturer(item.manufacturer));
    }

    if (this.config.enableCrossFieldValidation) {
      results.push(...this.validateCrossField(item));
    }

    // ── Aggregate Results ──────────────────────────────────────────
    const criticalIssues = results
      .filter(r => r.severity === BusinessRuleSeverity.CRITICAL && !r.isValid)
      .flatMap(r => r.issues);

    const warnings = results
      .filter(r => r.severity === BusinessRuleSeverity.WARNING && !r.isValid)
      .flatMap(r => r.issues);

    const validResults = results.filter(r => r.isValid);
    const overallConfidence = results.length > 0
      ? Math.round(results.reduce((sum, r) => sum + r.confidence, 0) / results.length)
      : 0;

    const hasCritical = results.some(r => r.severity === BusinessRuleSeverity.CRITICAL && !r.isValid);
    const hasWarning = results.some(r => r.severity === BusinessRuleSeverity.WARNING && !r.isValid);

    let overallSeverity: BusinessRuleSeverity;
    if (hasCritical) {
      overallSeverity = BusinessRuleSeverity.CRITICAL;
    } else if (hasWarning) {
      overallSeverity = BusinessRuleSeverity.WARNING;
    } else {
      overallSeverity = BusinessRuleSeverity.INFO;
    }

    return {
      itemId: item.id,
      results,
      overallConfidence,
      overallSeverity,
      isUsable: criticalIssues.length === 0 && validResults.length >= 4,
      criticalIssues,
      warnings,
      autoCorrections,
    };
  }

  /**
   * Validate a batch of items and provide aggregate results
   */
  validateBatch(items: ParsedItem[]): BatchBusinessRulesResult {
    const results = items.map(item => this.validateItem(item));
    
    const usableItems = results.filter(r => r.isUsable).length;
    const itemsNeedingReview = results.filter(r => !r.isUsable).length;
    
    const totalCriticalIssues = results.reduce((sum, r) => sum + r.criticalIssues.length, 0);
    const totalWarnings = results.reduce((sum, r) => sum + r.warnings.length, 0);
    const totalAutoCorrections = results.reduce((sum, r) => sum + r.autoCorrections.length, 0);
    
    const overallConfidence = results.length > 0
      ? Math.round(results.reduce((sum, r) => sum + r.overallConfidence, 0) / results.length)
      : 0;

    // Collect fields that consistently have low confidence
    const lowConfidenceFields = new Map<string, number>();
    for (const result of results) {
      for (const rule of result.results) {
        if (rule.confidence < this.config.reviewThreshold) {
          lowConfidenceFields.set(rule.field, (lowConfidenceFields.get(rule.field) || 0) + 1);
        }
      }
    }
    const fieldsWithLowConfidence = [...lowConfidenceFields.entries()]
      .filter(([_, count]) => count > results.length * 0.5)
      .map(([field]) => field);

    const autoSaveEligible = overallConfidence >= this.config.autoCorrectThreshold &&
      itemsNeedingReview === 0 &&
      fieldsWithLowConfidence.length === 0;

    return {
      totalItems: items.length,
      usableItems,
      itemsNeedingReview,
      overallConfidence,
      autoSaveEligible,
      results,
      summary: {
        totalCriticalIssues,
        totalWarnings,
        totalAutoCorrections,
        fieldsWithLowConfidence,
        suggestedManualReview: !autoSaveEligible,
      },
    };
  }

  /**
   * Check if auto-correction should be applied based on confidence
   */
  shouldAutoCorrect(confidence: number): boolean {
    return confidence >= this.config.autoCorrectThreshold;
  }

  /**
   * Check if manual review is needed based on confidence
   */
  needsReview(confidence: number): boolean {
    return confidence < this.config.reviewThreshold;
  }

  // ═════════════════════════════════════════════════════════════════
  // INDIVIDUAL FIELD VALIDATORS
  // ═════════════════════════════════════════════════════════════════

  /**
   * Validate medicine name against pharmacy rules
   * Rules: length, characters, no numbers at start, no garbage patterns
   */
  private validateMedicineName(value: string, item: ParsedItem): BusinessRuleResult {
    const rulesApplied: string[] = [];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;
    let normalizedValue = value?.trim() || '';
    let autoCorrected = false;

    rulesApplied.push('medicine_name_length_check');
    rulesApplied.push('medicine_name_chars_check');
    rulesApplied.push('medicine_name_prefix_check');
    rulesApplied.push('medicine_name_garbage_check');

    if (!value || value.trim().length === 0) {
      return {
        field: 'name',
        fieldType: BusinessFieldType.MEDICINE_NAME,
        originalValue: value || '',
        normalizedValue: '',
        isValid: false,
        confidence: 0,
        severity: BusinessRuleSeverity.CRITICAL,
        rulesApplied,
        issues: ['Medicine name is missing - cannot process item'],
        suggestions: ['Enter medicine name manually from physical invoice'],
        autoCorrected: false,
      };
    }

    // Rule 1: Minimum length
    if (normalizedValue.length < MEDICINE_NAME.minLength) {
      issues.push(`Medicine name "${normalizedValue}" is too short (min ${MEDICINE_NAME.minLength} chars)`);
      confidence -= 35;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    // Rule 2: Maximum length
    if (normalizedValue.length > MEDICINE_NAME.maxLength) {
      issues.push(`Medicine name "${normalizedValue}" exceeds max length of ${MEDICINE_NAME.maxLength} chars`);
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
    }

    // Rule 3: Must start with a letter
    if (!MEDICINE_NAME.startsWithLetter.test(normalizedValue)) {
      issues.push('Medicine name must start with a letter');
      confidence -= 40;
      severity = BusinessRuleSeverity.CRITICAL;
      
      // Try auto-correct: remove leading non-letters
      const corrected = normalizedValue.replace(/^[^a-zA-Z]+/, '');
      if (corrected.length >= MEDICINE_NAME.minLength) {
        normalizedValue = corrected;
        autoCorrected = true;
        suggestions.push(`Auto-corrected to "${corrected}"`);
      }
    }

    // Rule 4: Must contain minimum alphabetic characters
    const alphaCount = (normalizedValue.match(/[a-zA-Z]/g) || []).length;
    if (alphaCount < MEDICINE_NAME.minAlphaChars) {
      issues.push(`Medicine name must contain at least ${MEDICINE_NAME.minAlphaChars} letters (found ${alphaCount})`);
      confidence -= 45;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    // Rule 5: Check for invalid characters
    if (!MEDICINE_NAME.pattern.test(normalizedValue)) {
      const cleaned = normalizedValue.replace(/[^a-zA-Z0-9\s().%\/\[\]\-]/g, ' ').replace(/\s+/g, ' ').trim();
      if (cleaned.length >= MEDICINE_NAME.minLength) {
        issues.push('Invalid characters found and removed');
        normalizedValue = cleaned;
        autoCorrected = true;
        confidence -= 10;
        severity = BusinessRuleSeverity.WARNING;
      } else {
        issues.push('Medicine name contains invalid characters');
        confidence -= 30;
        severity = BusinessRuleSeverity.CRITICAL;
      }
    }

    // Rule 6: Check for embedded dates (OCR error)
    if (MEDICINE_NAME.noDates.test(normalizedValue)) {
      issues.push('Date pattern detected in medicine name - possible OCR error');
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Remove date from medicine name field');
    }

    // Rule 7: Check for OCR garbage patterns
    if (/^[\d\s.]+$/.test(normalizedValue)) {
      issues.push('Medicine name consists only of numbers - likely OCR error');
      confidence -= 50;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    // Rule 8: Check if batch number is embedded in name
    if (item.batchNumber && normalizedValue.toUpperCase().includes(item.batchNumber.toUpperCase())) {
      issues.push('Batch number appears within medicine name');
      confidence -= 10;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Separate batch number from medicine name');
    }

    // Rule 9: Check for known medicine name patterns
    const hasMedicineKeyword = /\b(?:tab|cap|inj|syp|oint|cream|drops|susp|soln)\b/i.test(normalizedValue);
    if (!hasMedicineKeyword && alphaCount >= MEDICINE_NAME.minAlphaChars) {
      // It might still be valid (many meds don't have dosage form keywords)
      // Just don't boost confidence
    }

    // Rule 10: Check for excess whitespace
    if (normalizedValue.includes('  ')) {
      normalizedValue = normalizedValue.replace(/\s+/g, ' ').trim();
      autoCorrected = true;
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'name',
      fieldType: BusinessFieldType.MEDICINE_NAME,
      originalValue: value,
      normalizedValue,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected,
    };
  }

  /**
   * Validate batch number format and content
   * Rules: format, length, no auto-generated, not a date
   */
  private validateBatchNumber(value: string): BusinessRuleResult {
    const rulesApplied: string[] = [
      'batch_format_check',
      'batch_length_check',
      'batch_auto_generated_check',
      'batch_date_check',
      'batch_digit_check',
    ];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;
    let autoCorrected = false;

    if (!value || value.trim().length === 0) {
      return {
        field: 'batchNumber',
        fieldType: BusinessFieldType.BATCH_NUMBER,
        originalValue: value || '',
        normalizedValue: '',
        isValid: false,
        confidence: 30,
        severity: BusinessRuleSeverity.CRITICAL,
        rulesApplied,
        issues: ['Batch number is missing - required for stock tracking'],
        suggestions: ['Enter batch number from physical product/invoice'],
        autoCorrected: false,
      };
    }

    let normalized = value.toUpperCase().trim();

    // Rule 1: Normalize - remove common OCR artifacts
    const cleaned = normalized.replace(/[^A-Z0-9\-]/g, '');
    if (cleaned !== normalized && cleaned.length >= BATCH_NUMBER.minLength) {
      normalized = cleaned;
      autoCorrected = true;
      issues.push('Removed invalid characters from batch number');
      confidence -= 5;
    }

    // Rule 2: Minimum length
    if (normalized.length < BATCH_NUMBER.minLength) {
      issues.push(`Batch number "${normalized}" is too short (min ${BATCH_NUMBER.minLength} chars)`);
      confidence -= 25;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    // Rule 3: Maximum length
    if (normalized.length > BATCH_NUMBER.maxLength) {
      issues.push(`Batch number "${normalized}" exceeds max length`);
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify batch number - may contain extra characters');
    }

    // Rule 4: Auto-generated batch detection
    if (BATCH_NUMBER.autoGenerated.test(normalized)) {
      issues.push('Auto-generated batch number detected - must verify');
      confidence -= 40;
      severity = BusinessRuleSeverity.CRITICAL;
      suggestions.push('Verify actual batch number from product packaging');
    }

    // Rule 5: Only digits (unusual for batch numbers)
    if (BATCH_NUMBER.onlyDigits.test(normalized)) {
      issues.push('Batch number consists only of digits');
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify - batch numbers typically contain letters');
    }

    // Rule 6: Looks like a date
    if (BATCH_NUMBER.looksLikeDate.test(normalized)) {
      issues.push('Batch number matches date pattern - may be mis-extracted');
      confidence -= 30;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Confirm this is a batch number and not an expiry date');
    }

    // Rule 7: Check for suspicious repeating patterns
    if (/(.)\1{4,}/.test(normalized)) {
      issues.push('Batch number has unusual repeating characters');
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
    }

    // Rule 8: Format validation
    if (!BATCH_NUMBER.pattern.test(normalized)) {
      issues.push('Batch number format is invalid');
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Batch number should be 3-15 alphanumeric characters');
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'batchNumber',
      fieldType: BusinessFieldType.BATCH_NUMBER,
      originalValue: value,
      normalizedValue: normalized,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected,
    };
  }

  /**
   * Validate expiry date
   * Rules: format, year range, not expired, mfg < expiry
   */
  private validateExpiryDate(expiryStr: string, mfgStr: string): BusinessRuleResult {
    const rulesApplied: string[] = [
      'expiry_format_check',
      'expiry_range_check',
      'expiry_not_expired_check',
      'expiry_vs_mfg_check',
    ];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!expiryStr || expiryStr.trim().length === 0) {
      return {
        field: 'expiryDate',
        fieldType: BusinessFieldType.EXPIRY_DATE,
        originalValue: expiryStr || '',
        normalizedValue: '',
        isValid: false,
        confidence: 30,
        severity: BusinessRuleSeverity.CRITICAL,
        rulesApplied,
        issues: ['Expiry date is missing - critical for FEFO management'],
        suggestions: ['Enter expiry date from product packaging'],
        autoCorrected: false,
      };
    }

    const normalized = this.normalizeDate(expiryStr);
    const expiryDate = new Date(normalized);
    const now = new Date();

    // Rule 1: Validate date format
    if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
      issues.push('Expiry date format is invalid');
      confidence -= 30;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    if (isNaN(expiryDate.getTime())) {
      issues.push('Expiry date is not a valid date');
      confidence -= 50;
      severity = BusinessRuleSeverity.CRITICAL;
      return {
        field: 'expiryDate',
        fieldType: BusinessFieldType.EXPIRY_DATE,
        originalValue: expiryStr,
        normalizedValue: normalized,
        isValid: false,
        confidence: Math.max(0, confidence),
        severity,
        rulesApplied,
        issues,
        suggestions: ['Enter a valid date in MM/YYYY or YYYY-MM-DD format'],
        autoCorrected: false,
      };
    }

    // Rule 2: Year range check
    if (expiryDate.getFullYear() < DATE.minExpiryYear) {
      issues.push(`Expiry year ${expiryDate.getFullYear()} is too far in the past`);
      confidence -= 40;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    if (expiryDate.getFullYear() > DATE.maxExpiryYear) {
      issues.push(`Expiry year ${expiryDate.getFullYear()} is too far in the future`);
      confidence -= 25;
      severity = BusinessRuleSeverity.WARNING;
    }

    // Rule 3: Check if already expired
    if (expiryDate < now) {
      const daysExpired = Math.floor((now.getTime() - expiryDate.getTime()) / (1000 * 60 * 60 * 24));
      issues.push(`Medicine already expired ${daysExpired} days ago`);
      confidence -= 20;
      severity = BusinessRuleSeverity.CRITICAL;
      suggestions.push('Do not accept expired medicines into stock');
    }

    // Rule 4: Check if expiring soon
    const thirtyDaysFromNow = new Date(now.getTime() + DATE.minExpiryWarningDays * 24 * 60 * 60 * 1000);
    if (expiryDate > now && expiryDate < thirtyDaysFromNow) {
      issues.push(`Medicine expires within ${DATE.minExpiryWarningDays} days`);
      confidence -= 10;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Consider negotiating return credit for near-expiry stock');
    }

    // Rule 5: Check expiry vs manufacturing date
    if (mfgStr) {
      const mfgDate = new Date(this.normalizeDate(mfgStr));
      if (!isNaN(mfgDate.getTime()) && expiryDate <= mfgDate) {
        issues.push('Expiry date is before or same as manufacturing date - impossible');
        confidence -= 40;
        severity = BusinessRuleSeverity.CRITICAL;
        suggestions.push('Verify both manufacturing and expiry dates');
      }
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 35;

    return {
      field: 'expiryDate',
      fieldType: BusinessFieldType.EXPIRY_DATE,
      originalValue: expiryStr,
      normalizedValue: normalized,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate manufacturing date
   * Rules: not in future, not too old, before expiry
   */
  private validateMfgDate(mfgStr: string, expiryStr: string): BusinessRuleResult {
    const rulesApplied: string[] = [
      'mfg_format_check',
      'mfg_future_check',
      'mfg_age_check',
    ];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!mfgStr || mfgStr.trim().length === 0) {
      return {
        field: 'mfgDate',
        fieldType: BusinessFieldType.MFG_DATE,
        originalValue: mfgStr || '',
        normalizedValue: '',
        isValid: true, // Mfg date is optional
        confidence: 60,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: ['Manufacturing date not found - optional field'],
        autoCorrected: false,
      };
    }

    const normalized = this.normalizeDate(mfgStr);
    const mfgDate = new Date(normalized);
    const now = new Date();

    if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized) || isNaN(mfgDate.getTime())) {
      return {
        field: 'mfgDate',
        fieldType: BusinessFieldType.MFG_DATE,
        originalValue: mfgStr,
        normalizedValue: normalized,
        isValid: false,
        confidence: 40,
        severity: BusinessRuleSeverity.WARNING,
        rulesApplied,
        issues: ['Manufacturing date format is invalid'],
        suggestions: ['Enter date in MM/YYYY format'],
        autoCorrected: false,
      };
    }

    // Rule 1: Not in future
    if (mfgDate > now) {
      issues.push('Manufacturing date is in the future');
      confidence -= 40;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    // Rule 2: Not too old
    const twoYearsAgo = new Date(now.getTime() - DATE.maxMfgAge * 365 * 24 * 60 * 60 * 1000);
    if (mfgDate < twoYearsAgo) {
      issues.push(`Manufacturing date is over ${DATE.maxMfgAge} years old`);
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Check if medicine is still within its shelf life');
    }

    // Rule 3: Before expiry
    if (expiryStr) {
      const expiryDate = new Date(this.normalizeDate(expiryStr));
      if (!isNaN(expiryDate.getTime()) && mfgDate >= expiryDate) {
        issues.push('Manufacturing date must be before expiry date');
        confidence -= 35;
        severity = BusinessRuleSeverity.CRITICAL;
      }
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'mfgDate',
      fieldType: BusinessFieldType.MFG_DATE,
      originalValue: mfgStr,
      normalizedValue: normalized,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate quantity
   * Rules: positive integer, reasonable range, no suspicious round numbers
   */
  private validateQuantity(value: number): BusinessRuleResult {
    const rulesApplied: string[] = [
      'qty_positive_check',
      'qty_range_check',
      'qty_round_number_check',
      'qty_integer_check',
    ];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (value === undefined || value === null || value <= 0) {
      return {
        field: 'quantity',
        fieldType: BusinessFieldType.QUANTITY,
        originalValue: String(value ?? ''),
        normalizedValue: '0',
        isValid: false,
        confidence: 30,
        severity: BusinessRuleSeverity.CRITICAL,
        rulesApplied,
        issues: ['Quantity is missing or zero'],
        suggestions: ['Enter quantity from invoice'],
        autoCorrected: false,
      };
    }

    // Rule 1: Must be finite number
    if (!Number.isFinite(value)) {
      return {
        field: 'quantity',
        fieldType: BusinessFieldType.QUANTITY,
        originalValue: String(value),
        normalizedValue: '0',
        isValid: false,
        confidence: 20,
        severity: BusinessRuleSeverity.CRITICAL,
        rulesApplied,
        issues: ['Invalid quantity value'],
        suggestions: ['Enter a valid number'],
        autoCorrected: false,
      };
    }

    // Rule 2: Should be integer (or close to it)
    if (!Number.isInteger(value)) {
      issues.push(`Quantity ${value} is not a whole number`);
      suggestions.push('Check if decimal quantity is correct');
      // Don't reduce confidence much - some items come in fractions
      confidence -= 5;
    }

    // Rule 3: Minimum check
    if (value < QUANTITY.min) {
      issues.push(`Quantity ${value} is below minimum (${QUANTITY.min})`);
      confidence -= 20;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    // Rule 4: Maximum check
    if (value > QUANTITY.max) {
      issues.push(`Quantity ${value} exceeds maximum (${QUANTITY.max}) - verify`);
      confidence -= 30;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify unusually large quantity');
    }

    // Rule 5: Suspicious round number for large quantities
    if (value >= QUANTITY.suspiciousRoundThreshold && value % 100 === 0) {
      issues.push(`Large round number quantity ${value} - verify accuracy`);
      confidence -= 10;
      severity = BusinessRuleSeverity.WARNING;
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'quantity',
      fieldType: BusinessFieldType.QUANTITY,
      originalValue: String(value),
      normalizedValue: String(Math.round(value)),
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate free quantity
   * Rules: not more than ordered quantity, reasonable range
   */
  private validateFreeQty(freeQty: number, orderedQty: number): BusinessRuleResult {
    const rulesApplied: string[] = ['free_qty_range_check', 'free_qty_vs_ordered_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;
    let isValid = true;

    if (!freeQty || freeQty <= 0) {
      return {
        field: 'freeQty',
        fieldType: BusinessFieldType.FREE_QTY,
        originalValue: String(freeQty ?? ''),
        normalizedValue: '0',
        isValid: true,
        confidence: 90,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: [],
        autoCorrected: false,
      };
    }

    if (orderedQty > 0 && freeQty > orderedQty * 2) {
      issues.push(`Free quantity (${freeQty}) is more than double ordered quantity (${orderedQty})`);
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify free quantity with supplier');
    }

    if (freeQty > 1000) {
      issues.push(`Free quantity ${freeQty} is unusually high`);
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    isValid = confidence >= 50;

    return {
      field: 'freeQty',
      fieldType: BusinessFieldType.FREE_QTY,
      originalValue: String(freeQty),
      normalizedValue: String(freeQty),
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate unit price (PTR/rate)
   * Rules: reasonable range, positive, not exceeding MRP
   */
  private validateUnitPrice(price: number, mrp: number, ptr: number): BusinessRuleResult {
    const rulesApplied: string[] = ['price_positive_check', 'price_range_check', 'price_vs_mrp_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!price || price <= 0) {
      return {
        field: 'unitPrice',
        fieldType: BusinessFieldType.UNIT_PRICE,
        originalValue: String(price ?? ''),
        normalizedValue: '0',
        isValid: true, // Price may be in a different column
        confidence: 60,
        severity: BusinessRuleSeverity.WARNING,
        rulesApplied,
        issues: [],
        suggestions: ['Unit price not found - may be in MRP or PTR column'],
        autoCorrected: false,
      };
    }

    // Rule 1: Not exceeding MRP (unless it's a different pricing type)
    if (mrp > 0 && price > mrp) {
      issues.push(`Unit price (${price}) exceeds MRP (${mrp})`);
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify - unit price should typically be less than MRP');
    }

    // Rule 2: Minimum price check
    if (price < PRICE.minPtr) {
      issues.push(`Unit price ${price} is unreasonably low`);
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
    }

    // Rule 3: Maximum price check
    if (price > PRICE.maxPtr) {
      issues.push(`Unit price ${price} is unusually high`);
      confidence -= 25;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify price with supplier invoice');
    }

    // Rule 4: Round number suspicion
    if (price >= 100 && price % 10 === 0 && price % 1 === 0) {
      confidence -= 5;
    }

    // Rule 5: Check decimal places
    const decimalStr = String(price);
    const decimalPart = decimalStr.includes('.') ? decimalStr.split('.')[1] : '';
    if (decimalPart.length > 2) {
      issues.push(`Unit price has ${decimalPart.length} decimal places - round to 2`);
      confidence -= 5;
      severity = BusinessRuleSeverity.INFO;
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 45;

    return {
      field: 'unitPrice',
      fieldType: BusinessFieldType.UNIT_PRICE,
      originalValue: price.toFixed(2),
      normalizedValue: price.toFixed(2),
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate MRP
   * Rules: must be >= unit price/PTR, reasonable range
   */
  private validateMRP(mrp: number, unitPrice: number): BusinessRuleResult {
    const rulesApplied: string[] = ['mrp_range_check', 'mrp_vs_price_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!mrp || mrp <= 0) {
      return {
        field: 'mrp',
        fieldType: BusinessFieldType.MRP,
        originalValue: String(mrp ?? ''),
        normalizedValue: '0',
        isValid: true,
        confidence: 70,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: ['MRP not found - may not be listed on invoice'],
        autoCorrected: false,
      };
    }

    if (mrp < PRICE.minMrp) {
      issues.push(`MRP ${mrp} is unreasonably low`);
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
    }

    if (mrp > PRICE.maxMrp) {
      issues.push(`MRP ${mrp} exceeds reasonable maximum`);
      confidence -= 25;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify MRP value');
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 45;

    return {
      field: 'mrp',
      fieldType: BusinessFieldType.MRP,
      originalValue: mrp.toFixed(2),
      normalizedValue: mrp.toFixed(2),
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate total amount
   * Rules: matches qty × unit price within tolerance
   */
  private validateTotalAmount(total: number, qty: number, unitPrice: number): BusinessRuleResult {
    const rulesApplied: string[] = ['total_calculation_check', 'total_range_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!total || total <= 0) {
      return {
        field: 'totalAmount',
        fieldType: BusinessFieldType.TOTAL_AMOUNT,
        originalValue: String(total ?? ''),
        normalizedValue: '0',
        isValid: true,
        confidence: 70,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: [],
        autoCorrected: false,
      };
    }

    // Rule 1: Check against qty × unit price
    if (qty > 0 && unitPrice > 0) {
      const expectedTotal = qty * unitPrice;
      const deviation = Math.abs(total - expectedTotal);
      const deviationPercent = (deviation / expectedTotal) * 100;

      if (deviationPercent > 10) {
        issues.push(`Total (${total.toFixed(2)}) deviates ${deviationPercent.toFixed(1)}% from qty×price (${expectedTotal.toFixed(2)})`);
        confidence -= 20;
        severity = BusinessRuleSeverity.WARNING;
        suggestions.push('Check for discounts or additional charges in total');
      } else if (deviationPercent > 2) {
        // Small deviation may be due to rounding or discount
        confidence -= 5;
        suggestions.push('Small difference may be due to discounts or rounding');
      }
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 45;

    return {
      field: 'totalAmount',
      fieldType: BusinessFieldType.TOTAL_AMOUNT,
      originalValue: total.toFixed(2),
      normalizedValue: total.toFixed(2),
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate GST rate
   * Rules: must be a valid Indian GST rate
   */
  private validateGSTRate(rate: number): BusinessRuleResult {
    const rulesApplied: string[] = ['gst_rate_valid_check', 'gst_rate_range_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (rate === undefined || rate === null) {
      return {
        field: 'gstRate',
        fieldType: BusinessFieldType.GST_RATE,
        originalValue: '',
        normalizedValue: '12',
        isValid: true,
        confidence: 70,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: ['GST rate not found - defaulting to 12%'],
        autoCorrected: false,
      };
    }

    if (!(GST.validRates as readonly number[]).includes(rate)) {
      issues.push(`GST rate ${rate}% is not a standard Indian GST rate`);
      confidence -= 20;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push(`Standard rates: ${GST.validRates.join(', ')}%`);
    }

    if (rate < 0 || rate > GST.maxRate) {
      issues.push(`GST rate ${rate}% is out of valid range (0-${GST.maxRate}%)`);
      confidence -= 25;
      severity = BusinessRuleSeverity.CRITICAL;
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'gstRate',
      fieldType: BusinessFieldType.GST_RATE,
      originalValue: String(rate),
      normalizedValue: String(rate),
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate GST amounts
   * Rules: CGST ≈ SGST for intra-state, IGST for inter-state
   */
  private validateGSTAmounts(
    gstRate: number,
    cgst: number,
    sgst: number,
    igst: number,
    taxableValue: number
  ): BusinessRuleResult {
    const rulesApplied: string[] = [
      'gst_amounts_check',
      'cgst_sgst_balance_check',
      'gst_vs_rate_check',
    ];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    const hasAnyGstAmount = cgst > 0 || sgst > 0 || igst > 0;

    if (!hasAnyGstAmount) {
      return {
        field: 'gstAmounts',
        fieldType: BusinessFieldType.CGST_AMOUNT,
        originalValue: '',
        normalizedValue: '',
        isValid: true,
        confidence: 70,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: ['GST amounts not found on invoice'],
        autoCorrected: false,
      };
    }

    // Rule 1: Check CGST ≈ SGST balance (for intra-state)
    if (cgst > 0 && sgst > 0) {
      const diff = Math.abs(cgst - sgst);
      if (diff > GST.cgstSgstTolerance) {
        issues.push(`CGST (${cgst.toFixed(2)}) and SGST (${sgst.toFixed(2)}) should be nearly equal`);
        confidence -= 15;
        severity = BusinessRuleSeverity.WARNING;
      }
    }

    // Rule 2: Check IGST mutually exclusive with CGST/SGST
    if (igst > 0 && (cgst > 0 || sgst > 0)) {
      issues.push('Both IGST and CGST/SGST present - should be one or the other');
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Verify GST type - inter-state (IGST) or intra-state (CGST+SGST)');
    }

    // Rule 3: Check tax amount vs rate × taxable value
    if (gstRate > 0 && taxableValue > 0) {
      const expectedTotalGst = (gstRate / 100) * taxableValue;
      
      if (igst > 0) {
        const diff = Math.abs(igst - expectedTotalGst);
        if (diff > expectedTotalGst * 0.1) {
          issues.push(`IGST amount does not match ${gstRate}% of taxable value`);
          confidence -= 10;
        }
      } else if (cgst > 0) {
        const expectedHalfGst = expectedTotalGst / 2;
        const cgstDiffPercent = Math.abs(cgst - expectedHalfGst) / expectedHalfGst * 100;
        if (cgstDiffPercent > 10) {
          issues.push(`CGST amount may not match ${gstRate / 2}% of taxable value`);
          confidence -= 10;
        }
      }
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 45;

    return {
      field: 'gstAmounts',
      fieldType: BusinessFieldType.GST_RATE,
      originalValue: `CGST:${cgst} SGST:${sgst} IGST:${igst}`,
      normalizedValue: `CGST:${cgst.toFixed(2)} SGST:${sgst.toFixed(2)} IGST:${igst.toFixed(2)}`,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate HSN code
   * Rules: 4-8 digits, starts with 30 for medicines
   */
  private validateHSNCode(value: string): BusinessRuleResult {
    const rulesApplied: string[] = ['hsn_format_check', 'hsn_prefix_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!value || value.trim().length === 0) {
      return {
        field: 'hsnCode',
        fieldType: BusinessFieldType.HSN_CODE,
        originalValue: value || '',
        normalizedValue: '3004',
        isValid: true,
        confidence: 60,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: ['HSN code not found - using default 3004 for medicines'],
        autoCorrected: false,
      };
    }

    const normalized = value.trim();

    if (!HSN.pattern.test(normalized)) {
      issues.push(`HSN code "${normalized}" format is invalid`);
      confidence -= 30;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('HSN code should be 4-8 digits');
    }

    if (normalized.length < HSN.minLength || normalized.length > HSN.maxLength) {
      issues.push(`HSN code length (${normalized.length}) out of range`);
      confidence -= 15;
    }

    if (!HSN.medicinePrefix.test(normalized) && !HSN.surgicalPrefix.test(normalized)) {
      issues.push(`HSN code "${normalized}" may not be for pharmaceutical products`);
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
      suggestions.push('Pharmaceutical HSN codes typically start with 30');
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'hsnCode',
      fieldType: BusinessFieldType.HSN_CODE,
      originalValue: value,
      normalizedValue: normalized,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Validate manufacturer name
   * Rules: known manufacturer, name format consistency
   */
  private validateManufacturer(value: string): BusinessRuleResult {
    const rulesApplied: string[] = ['mfr_length_check', 'mfr_known_check'];
    const issues: string[] = [];
    const suggestions: string[] = [];
    let confidence = 100;
    let severity = BusinessRuleSeverity.INFO;

    if (!value || value.trim().length === 0) {
      return {
        field: 'manufacturer',
        fieldType: BusinessFieldType.MANUFACTURER,
        originalValue: value || '',
        normalizedValue: '',
        isValid: true,
        confidence: 65,
        severity: BusinessRuleSeverity.INFO,
        rulesApplied,
        issues: [],
        suggestions: ['Manufacturer name not found'],
        autoCorrected: false,
      };
    }

    const normalized = value.trim();

    if (normalized.length < MANUFACTURER.minLength) {
      issues.push('Manufacturer name is too short');
      confidence -= 15;
      severity = BusinessRuleSeverity.WARNING;
    }

    if (normalized.length > MANUFACTURER.maxLength) {
      issues.push('Manufacturer name exceeds max length');
      confidence -= 10;
    }

    // Check against known manufacturers
    const normalizedLower = normalized.toLowerCase();
    const isKnown = [...KNOWN_MANUFACTURERS].some(mfr => normalizedLower.includes(mfr));
    if (isKnown) {
      confidence = Math.min(100, confidence + 10);
    }

    confidence = Math.max(0, Math.min(100, Math.round(confidence)));
    const isValid = confidence >= 40;

    return {
      field: 'manufacturer',
      fieldType: BusinessFieldType.MANUFACTURER,
      originalValue: value,
      normalizedValue: normalized,
      isValid,
      confidence,
      severity,
      rulesApplied,
      issues,
      suggestions,
      autoCorrected: false,
    };
  }

  /**
   * Cross-field validation
   * Checks relationships between multiple fields for consistency
   */
  private validateCrossField(item: ParsedItem): BusinessRuleResult[] {
    const results: BusinessRuleResult[] = [];

    // Check 1: Total amount = qty × unit price (with tolerance for discounts)
    if (item.quantity > 0 && item.unitPrice > 0 && item.totalAmount > 0) {
      const expectedTotal = item.quantity * item.unitPrice;
      const diff = Math.abs(item.totalAmount - expectedTotal);
      const diffPercent = (diff / expectedTotal) * 100;

      if (diffPercent > 20) {
        results.push({
          field: 'cross_field_total',
          fieldType: BusinessFieldType.TOTAL_AMOUNT,
          originalValue: `qty×price=${expectedTotal.toFixed(2)}, total=${item.totalAmount.toFixed(2)}`,
          normalizedValue: item.totalAmount.toFixed(2),
          isValid: true,
          confidence: 60,
          severity: BusinessRuleSeverity.WARNING,
          rulesApplied: ['cross_field_total_calculation'],
          issues: [`Total (${item.totalAmount.toFixed(2)}) significantly differs from qty×unitPrice (${expectedTotal.toFixed(2)})`],
          suggestions: ['Check for discounts, scheme, or separate GST line items'],
          autoCorrected: false,
        });
      }
    }

    // Check 2: MRP should be >= unit price (PTR)
    if (item.mrp > 0 && item.unitPrice > 0 && item.unitPrice > item.mrp) {
      results.push({
        field: 'cross_field_mrp_price',
        fieldType: BusinessFieldType.MRP,
        originalValue: `MRP=${item.mrp}, UnitPrice=${item.unitPrice}`,
        normalizedValue: String(item.mrp),
        isValid: true,
        confidence: 65,
        severity: BusinessRuleSeverity.WARNING,
        rulesApplied: ['cross_field_mrp_vs_price'],
        issues: [`Unit price (${item.unitPrice}) exceeds MRP (${item.mrp}) - verify free scheme`],
        suggestions: ['Check if this is a free/scheme item or pricing error'],
        autoCorrected: false,
      });
    }

    // Check 3: Quantity should be reasonable for strip/vial packaging
    if (item.quantity > 100 && item.packSize && /strip|tablet|cap/i.test(item.packSize)) {
      // Large quantity in strips might be correct, but note it
      // No action needed - this is common for generics
    }

    // Check 4: Batch number should not match expiry date
    if (item.batchNumber && item.expiryDate) {
      const batchNorm = item.batchNumber.toUpperCase().replace(/[^A-Z0-9]/g, '');
      const expiryNorm = item.expiryDate.replace(/[^0-9]/g, '');
      if (batchNorm.includes(expiryNorm) || expiryNorm.includes(batchNorm)) {
        results.push({
          field: 'cross_field_batch_expiry',
          fieldType: BusinessFieldType.BATCH_NUMBER,
          originalValue: `Batch=${item.batchNumber}, Expiry=${item.expiryDate}`,
          normalizedValue: item.batchNumber,
          isValid: true,
          confidence: 70,
          severity: BusinessRuleSeverity.WARNING,
          rulesApplied: ['cross_field_batch_expiry_similarity'],
          issues: ['Batch number and expiry date appear similar - possible data duplication'],
          suggestions: ['Verify batch number and expiry date are distinct values'],
          autoCorrected: false,
        });
      }
    }

    return results;
  }

  /**
   * Normalize date value to YYYY-MM-DD format
   */
  private normalizeDate(value: string): string {
    const patterns = [
      /^(\d{1,2})[\/\-\.](\d{2,4})$/,           // MM/YYYY or MM/YY
      /^(\d{4})[\/\-\.](\d{2})[\/\-\.](\d{2})$/, // YYYY-MM-DD
      /^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/, // DD/MM/YYYY or MM/DD/YYYY
    ];

    for (const pattern of patterns) {
      const match = value.match(pattern);
      if (match) {
        if (match.length === 3) {
          const month = match[1].padStart(2, '0');
          const year = match[2].length === 2 ? '20' + match[2] : match[2];
          return `${year}-${month}-01`;
        } else if (match.length === 4) {
          let year: string, month: string, day: string;

          if (match[1].length === 4) {
            // YYYY-MM-DD
            year = match[1];
            month = match[2];
            day = match[3];
          } else {
            // Could be DD-MM-YYYY or MM-DD-YYYY
            const p1 = parseInt(match[1]);
            const p2 = parseInt(match[2]);
            year = match[3].length === 2 ? '20' + match[3] : match[3];

            if (p1 > 12) {
              // DD-MM-YYYY
              day = match[1].padStart(2, '0');
              month = match[2].padStart(2, '0');
            } else if (p2 > 12) {
              // MM-DD-YYYY
              month = match[1].padStart(2, '0');
              day = match[2].padStart(2, '0');
            } else {
              // Ambiguous, assume DD-MM-YYYY (Indian convention)
              day = match[1].padStart(2, '0');
              month = match[2].padStart(2, '0');
            }
          }

          return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
        }
      }
    }

    return value;
  }
}

// ── Singleton instance ───────────────────────────────────────────────

export const businessRulesEngine = new BusinessRulesEngine();
